<div class="entity-split"><section class="panel"><header class="panel-head"><div><span class="eyebrow">Template history</span><h2>Applications and rollback evidence</h2></div><span class="panel-meta"><?= count($applications) ?> application(s)</span></header><div class="record-list"><?php foreach($applications as$a): ?><article class="record-card"><header><div><strong><?= h($a['application_number'].' · '.status_label($a['template_code'])) ?></strong><small>Version <?= h($a['template_version']) ?> · hash <?= h(substr($a['relationship_hash'],0,12)) ?></small></div><?= badge($a['status']) ?></header><p><?= h($a['evidence_note']) ?></p><?php if($a['status']==='applied'&&can('companies.administer')): ?><form class="inline-actions" action="<?= h(app_url('entity-system-action.php')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="action" value="rollback_template"><input type="hidden" name="application_id" value="<?= (int)$a['id'] ?>"><input type="hidden" name="return_tab" value="governance"><input name="rollback_note" placeholder="Rollback evidence" required><button class="button ghost">Controlled Rollback</button></form><?php endif; ?></article><?php endforeach; ?></div></section><section class="panel"><header class="panel-head"><div><span class="eyebrow">Integration control</span><h2>Events and conflicts</h2></div></header><p><strong><?= count(entity_system_integration_events()) ?></strong> integration event(s), <strong><?= count($conflicts) ?></strong> conflict(s).</p><div class="record-list"><?php foreach(array_slice(entity_system_integration_events(),0,10)as$e): ?><article class="record-card"><strong><?= h(status_label($e['event_type'])) ?></strong><small><?= h($e['direction']) ?> · <?= h(substr($e['idempotency_key'],0,14)) ?> · <?= h($e['status']) ?></small><p><?= h($e['evidence_note']) ?></p></article><?php endforeach; ?></div></section></div>
<section class="panel"><header class="panel-head"><div><span class="eyebrow">Immutable entity history</span><h2>Governance events</h2></div><span class="panel-meta"><?= count($events) ?> event(s)</span></header><div class="table-wrap"><table><thead><tr><th>When</th><th>Event</th><th>Entity type</th><th>Status</th><th>Evidence</th></tr></thead><tbody><?php foreach($events as$e): ?><tr><td><?= h(date_us($e['created_at'],true)) ?></td><td><?= h(status_label($e['event_type'])) ?></td><td><?= h(status_label($e['entity_type'])) ?></td><td><?= h(($e['from_status']??'').' → '.($e['to_status']??'')) ?></td><td><?= h($e['evidence_note']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
